def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: if supply is tight relative to our requirement, we bid more.
    # With supply in [15,25], we likely need to secure water when hp is low.
    tightness = 1.0
    if supply >= 2.5 * WATER_REQ:
        tightness = 0.8
    elif supply <= 1.7 * WATER_REQ:
        tightness = 1.15

    # Base target bid depending on observed opponent aggression.
    # Use thresholds relative to our daily salary.
    if max_prev_bid >= 0.85 * DAILY_SALARY:
        target = 0.75 * DAILY_SALARY
    elif max_prev_bid >= 0.70 * DAILY_SALARY:
        target = 0.65 * DAILY_SALARY
    else:
        target = 0.55 * DAILY_SALARY

    # Adjust for our health/budget.
    if hp <= 2.0:
        target *= 1.25
    elif hp <= 4.0:
        target *= 1.10
    else:
        target *= 0.95

    # If we've already missed water multiple days, we must secure more.
    if no_water_days >= 2:
        target *= 1.15

    # Final scaling by tightness.
    target *= tightness

    # Don't exceed budget; also ensure non-negative.
    bid = max(0.0, min(budget, target))

    # If budget is extremely small, bid conservatively.
    if budget <= 10.0:
        bid = min(budget, 10.0)

    # Small deterministic nudge by day to avoid ties.
    bid += (0.1 if (day % 2 == 0) else 0.0)
    bid = max(0.0, min(budget, bid))

    return float(bid)

