def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    current_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.95)
    elif my_hp <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.8)

    day_factor = (current_day - 1) / (EPISODE_DAYS - 1) if EPISODE_DAYS > 1 else 0
    current_bid += (DAILY_SALARY * 0.2) * day_factor

    MIN_SUPPLY = 15.0
    MAX_SUPPLY = 25.0
    supply_range_val = MAX_SUPPLY - MIN_SUPPLY
    supply_pressure_factor = 0
    if supply_range_val > 0:
        supply_pressure_factor = (MAX_SUPPLY - current_supply) / supply_range_val
        current_bid += (DAILY_SALARY * 0.15) * supply_pressure_factor

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            if my_hp <= 3 or supply_pressure_factor > 0.5:
                current_bid = max(current_bid, highest_prev_bid + 2)
            else:
                current_bid = max(current_bid, highest_prev_bid + 1)
        elif highest_prev_bid < DAILY_SALARY * 0.4:
            current_bid = min(current_bid, highest_prev_bid + 10)
            current_bid = max(current_bid, DAILY_SALARY * 0.3)

    final_bid = min(my_budget, current_bid)
    final_bid = max(1, final_bid)

    return final_bid
